"""Writes boss/rimefall/RimefallDesigns.java: the candidates' labels, names, measured sizes and blocks (generated)."""

HEADER = """package com.reg21meme.dross.boss.rimefall;

import java.util.List;

/**
 * The Rimefall candidates the user picked (round 2, October 18, 2026): the Ice Necromancer (the Snow Angel, both
 * versions), its three servants, the hand kept for its fight, and Rimefall's regular mobs; frozen models shown side by
 * side by {@code /dross showcase boss_designs rimefall}. Only the looks: they don't move, fight or make a sound.
 * <p>
 * <b>Generated by {@code tools/rimefall/build.py}; don't edit by hand.</b> {@code number} is unique (gallery order),
 * {@code label} is what the sign says ("1A": design 1, variant A). Sizes are measured from the models, in blocks: the
 * hitbox ({@code width} x {@code height}), how far the model reaches in front of its feet ({@code front}), behind them
 * ({@code back}), to its own left and right ({@code left}, {@code right}) and up ({@code top}); which of its textures
 * exist ({@code <id>_glow.png}, {@code <id>_ice.png} (see-through ice), {@code <id>_iceglow.png}); and the real
 * Minecraft blocks drawn with it ({@code blocks}, see {@link Placed}).
 */
public final class RimefallDesigns
{
    /**
     * A real Minecraft block drawn with a model (the Fisher's bait house): its block state, and its lowest corner in the
     * model's own units (Bedrock: 16 a block, x to the model's own left, z to its back). {@code bright}: drawn
     * full-bright (a lit lantern).
     */
    public record Placed(float x, float y, float z, String state, boolean bright)
    {
    }

    /** One candidate. */
    public record Design(int number, String label, String id, String name, String mood, boolean boss, float width,
                         float height, float front, float back, float left, float right, float top, float shadow,
                         boolean hasGlow, boolean hasIce, boolean hasIceGlow, List<Placed> blocks)
    {
        /** How far the model reaches from its feet in any direction across the ground (blocks). */
        public float reach()
        {
            return Math.max(Math.max(this.front, this.back), Math.max(this.left, this.right));
        }
    }

    /** Every candidate, in gallery order: the bosses first, then the regular mobs. */
    public static final List<Design> ALL = List.of(
"""

HUNTERS = """    );

    /**
     * The hunters of the hunter villages (the user, October 23, 2026: "10-12 villagers that can spawn, 2 blocks tall,
     * that are similar to the Huntsman"): designs to pick from, worn by the same frozen statues but not in the
     * gallery ({@code boss} false); numbered after it.
     */
    public static final List<Design> HUNTERS = List.of(
"""

FOOTER = """    );

    /** The candidate (or hunter) with this number (the first candidate if there's none). */
    public static Design byNumber(int number)
    {
        for (Design design : ALL)
        {
            if (design.number() == number)
            {
                return design;
            }
        }
        for (Design design : HUNTERS)
        {
            if (design.number() == number)
            {
                return design;
            }
        }
        return ALL.get(0);
    }

    private RimefallDesigns() {}
}
"""


def _f(x):
    return f"{x:.2f}F"


def _s(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _blocks(placed):
    if not placed:
        return "List.of()"
    rows = [f"new Placed({_f(c[0])}, {_f(c[1])}, {_f(c[2])}, {_s(state)}, {str(bright).lower()})"
            for state, c, bright in placed]
    return "List.of(\n                    " + ",\n                    ".join(rows) + ")"


def entry(e, size, placed):
    return (f"            new Design({e.number}, {_s(e.label)}, {_s(e.id)}, {_s(e.name)}, {_s(e.mood)}, "
            f"{str(e.section == 'boss').lower()}, {_f(size['width'])}, {_f(size['height'])}, {_f(size['front'])}, "
            f"{_f(size['back'])}, {_f(size['left'])}, {_f(size['right'])}, {_f(size['top'])}, {_f(size['shadow'])}, "
            f"{str(size['glow']).lower()}, {str(size['ice']).lower()}, {str(size['iceglow']).lower()}, "
            f"{_blocks(placed)})")


def write(path, entries, hunters=()):
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(HEADER)
        f.write(",\n".join(entries) + "\n")
        f.write(HUNTERS)                     # (always: byNumber reads it)
        f.write(",\n".join(hunters) + "\n")
        f.write(FOOTER)
